namespace Jrpg.Core.Maps;

/// <summary>One tile type: whether it can be walked on, and the tilesheet cell it's drawn from. Ids are generated by the map editor.</summary>
public sealed record TileDefinition
{
    public required int Id { get; init; }

    public required bool IsWalkable { get; init; }

    /// <summary>The <see cref="TilesheetDefinition.Id"/> of the sheet holding the tile's image.</summary>
    public required string SheetId { get; init; }

    /// <summary>The cell's column in the sheet's grid, from 0.</summary>
    public required int Column { get; init; }

    /// <summary>The cell's row in the sheet's grid, from 0.</summary>
    public required int Row { get; init; }

    /// <summary>
    /// Null for a still tile. The frames are the tile's own cell and the cells to its right on the same row (ADR 0039).
    /// </summary>
    public TileAnimation? Animation { get; init; }

    /// <summary>The column drawn after <paramref name="elapsed"/>: <see cref="Column"/> for a still tile.</summary>
    public int ColumnShownAt(TimeSpan elapsed) => Column + (Animation?.FrameAt(elapsed) ?? 0);
}
